const LN2 = Math.LN2, log2 = Math.log2;
function solve(N, K, a1) {
  const a = new Float64Array(N + 1);
  a[1] = a1;
  for (let n = 2; n <= N; n++) {
    let s = 0.0;
    for (let j = 1; j < n; j++) s += a[j] * a[n - j];
    a[n] = Math.sqrt(s / K);
  }
  return a;
}
function analyze(a, K, label) {
  const N = a.length - 1;
  const pts = [];
  for (let n = 2; n <= N; n *= 2) pts.push(n);
  const z = pts.map(log2), phi = pts.map(n => log2(a[n]));
  console.log("'`--- ${label} ---`);
  console.log('"'z      resid      q(->c0-1/4ln2)');
  for (let i = 2; i < pts.length; i++) {
    const d1 = phi[i] - phi[i-1];
    const d2 = phi[i] - 2*phi[i-1] + phi[i-2];
    const p1 = (phi[i] - phi[i-2]) / 2;          // phi'(z-1)
    const H2 = 8 * (p1 - d2 / LN2);              // |H''| at saddle
    const lhs = z[i] + 0.5 * log2(2 * Math.PI / H2);
    const rhs = log2(K) + 2 * d1;
    const zm = z[i] - 0.5, L = log2(zm);
    const q = d1 - zm / 2 + L / 4;               // -> c0 - 1/(4 ln2)
    console.log(z[i].toFixed(1).padStart(5) + ' ' + (lhs - rhs).toFixed(6).padStart(10) + ' ' + q.toFixed(6).padStart(10));
  }
  // fit with c2, c1 fixed; free c0, d1, d0, e
  function fit(zmin) {
    const rows = [];
    for (let i = 0; i < pts.length; i++) {
      if (z[i] < zmin) continue;
      const L = log2(z[i]);
      const base = 0.25 * z[i] * z[i] - 0.25 * z[i] * L;
      rows.push([z[i], L * L, L, 1, phi[i] - base]);
    }
    const m = 4, A = Array.from({length: m}, () => new Float64Array(m + 1));
    for (const r of rows) for (let i = 0; i < m; i++) { for (let j = 0; j < m; j++) A[i][j] += r[i] * r[j]; A[i][m] += r[i] * r[m]; }
    for (let c = 0; c < m; c++) { let p = c; for (let r = c + 1; r < m; r++) if (Math.abs(A[r][c]) > Math.abs(A[p][c])) p = r;
      const t = A[c]; A[c] = A[p]; A[p] = t; const d = A[c][c]; for (let j = c; j <= m; j++) A[c][j] /= d;
      for (let r = 0; r < m; r++) { if (r === c) continue; const f = A[r][c]; for (let j = c; j <= m; j++) A[r][j] -= f * A[c][j]; } }
    const c = A.map(row => row[m]);
    console.log("'`fit z>=${zmin}: c0=${c[0].toFixed(5)} d1=${c[1].toFixed(5)} d0=${c[2].toFixed(5)} e=${c[3].toFixed(5)}`);
  }
  fit(6); fit(8); fit(10);
}
const N = 50000;
analyze(solve(N, 1.0, 1.0), 1.0, '"'K=1, a1=1');
analyze(solve(N, 1.0, 2.0), 1.0, 'K=1, a1=2 (scaled x2)');
analyze(solve(N, 4.0, 1.0), 4.0, 'K=4, a1=1');
console.log('theory c0 (bulk-fixed): ' + (0.25*log2(Math.PI/4) + 0.5 + 1/(4*LN2)).toFixed(5) + ' - 0.5*log2(K)');
