import numpy as np
from scipy.optimize import differential_evolution, minimize

def rel(p,q):
    p=np.asarray(p,float); q=np.asarray(q,float); out=0.
    for pi,qi in zip(p,q):
      if pi>1e-15:
        if qi<=1e-15: return np.inf
        out += pi*np.log(pi/qi)
    return out

def channel_val(r,g):
    # input Bloch vector (x,y,z), output
    x,y,z=r
    return np.array([np.sqrt(1-g)*x,np.sqrt(1-g)*y,g+(1-g)*z])

def eig(v):
    l=min(np.linalg.norm(v),1)
    return np.array([(1-l)/2,(1+l)/2])

def ratio_raw(v,g):
    rho,sig=v[:3],v[3:6]
    nr=np.linalg.norm(rho); ns=np.linalg.norm(sig)
    if nr>1 or ns>1: return 1.
    p=eig(rho); q=eig(sig)
    den=rel(p,q)
    if den<=1e-14: return 1.
    cp=channel_val(rho,g); cq=channel_val(sig,g)
    num=rel(eig(cp),eig(cq))
    if np.isfinite(num):
      return num/den
    return 1.

