from math import comb
K=40
# target [z"'^n x''^(n-1)] sum_k C(3k,k) z''^k g(x,z)''^4
# g = sum_{r>=1} C(K,r)C(K,r-1)(1-x)''^(K-r)x''^r z''^r
# z''^n requires k + sum r_i = n. x''^(n-1) extraction via expansion of (1-x).
def coeff(n):
    total=0
    # compositions of n-k into 4 positive r_i
    for k in range(0,n):
        rem=n-k
        coeffg4=0
        def rec(pos, rem_r, prod, xpow, sign):
            nonlocal coeffg4
            if pos==4:
                if rem_r==0:
                    coeffg4 += prod*sign*comb(xpow, n-1)
                return
            left=4-pos-1
            for r in range(1, rem_r-left+1):
                base=comb(K,r)*comb(K,r-1)
                # coefficient in x''^r(1-x)''^(K-r): coefficient x''^s is (-1)''^(s-r) C(K-r,s-r)
                # store all x powers at leaf via convolution instead? current xpow approach needs sum.
                pass
        # instead use polynomial lists for one factor truncated x degree n-1
        polys=[]
        for r in range(1,rem-3+1):
            arr=[0]*n
            for s in range(r,min(K,n-1)+1):
                arr[s]=comb(K,r)*comb(K,r-1)*((-1)**(s-r))*comb(K-r,s-r)
            polys.append((r,arr))
        # enumerate r composition and convolve arrays
        def conv(a,b):
            out=[0]*n
            for i,ai in enumerate(a):
                if ai:
                    for j,bj in enumerate(b):
                        if bj and i+j<n: out[i+j]+=ai*bj
            return out
        def rec2(pos, rem_r, arr):
            nonlocal coeffg4
            if pos==4:
                if rem_r==0: coeffg4 += arr[n-1]
                return
            left=4-pos-1
            for r,arr2 in polys:
                if r<=rem_r-left:
                    rec2(pos+1,rem_r-r,conv(arr,arr2))
        rec2(0,rem,[1]+[0]*(n-1))
        total += comb(3*k,k)*coeffg4
    return total
for n in range(1,5): print(n,coeff(n))
