import numpy as np
from functools import reduce
X=np.array([[0,1],[1,0]],complex);Y=np.array([[0,-1j],[1j,0]]);Z=np.diag([1,-1]);I=np.eye(2);P={'x':X,'y':Y,'z':Z}
def op(i,p):return reduce(np.kron,[P[p] if k==i else I for k in range(6)])
H=-(op(0,'z')@op(1,'z')+op(1,'y')@op(2,'y')+op(2,'x')@op(3,'x')+op(3,'z')@op(4,'z')+op(4,'y')@op(5,'y')+op(5,'x')@op(0,'x'))
K=np.eye(64)
for i,j,t in [(0,1,'z'),(1,2,'y'),(2,3,'x'),(3,4,'z'),(4,5,'y'),(5,0,'x')]:K=K@(op(i,t)@op(j,t))
print('K comm',np.max(np.abs(H@K-K@H)),'square',np.max(np.abs(K@K-np.eye(64))))
# compare K to local product one-site labels all permutations pattern by action nonzero
# derive each site's effective pauli from K sparse at basis 0
for i in range(6):
 for name in 'xyz':
  O=op(i,name)
  ov=np.vdot(O[:,0],K[:,0])
  if abs(ov)>1e-8:print(i,name,ov)
