import numpy as np
for m in [4,5,100]:
 N=m*(m+1); A=np.zeros((N,N),int)
 for i in range(m+1):
  idx=np.arange(i*m,(i+1)*m); A[np.ix_(idx,idx)]=1; np.fill_diagonal(A[np.ix_(idx,idx)],0)
 for i in range(m+1):
  for j in range(i+1,m+1):
   u=i*m+(j-1 if j>0 else m-1); v=j*m+(i-1 if i>0 else m-1); A[u,v]=A[v,u]=1
 # BFS on distance profiles from marked vertex 0 and neighbor roles perhaps signatures iterated stable refinement
 colors=np.zeros(N,dtype=int); colors[0]=1
 for _ in range(10):
  sig=[(colors[v],tuple(sorted(colors[A[v].astype(bool)]))) for v in range(N)]
  uniq={x:k for k,x in enumerate(sorted(set(sig)))}
  new=np.array([uniq[x] for x in sig])
  if np.array_equal(new,colors):break
  colors=new
 print('m',m,'classes',[(k,int(np.sum(colors==k))) list(zip(*np.unique(colors,return_counts=True))) if False else list(zip(*np.unique(colors,return_counts=True)))])
